function aiPage(action:AiActionType):Page{return({OPEN_SPACE_RESCUE:"Space Rescue",OPEN_DUPLICATES:"Duplicates",OPEN_LARGE_FILES:"Large Files",OPEN_STORAGE:"Storage",OPEN_TIMELINE:"Timeline",OPEN_DEVELOPER_STORAGE:"Developer Storage"}as const)[action]}
const quickAiQuestions=["Why is my disk full?","What changed recently?","Help me free 50 GB","What's using the most space?"];
