function providerLabel(providerId:string){
 if(providerId==="openrouter")return "OpenRouter";
 if(providerId==="groq")return "Groq";
 if(providerId==="spacepilot_hosted")return "SpacePilot AI";
 return "Local only";
}
function providerNotice(providerId:string){
 if(providerId==="openrouter")return "Using your OpenRouter key from Windows Credential Manager. Free-model availability is controlled by OpenRouter and may change.";
 if(providerId==="groq")return "Using your Groq key from Windows Credential Manager. Free-model availability is controlled by Groq and may change.";
 if(providerId==="spacepilot_hosted")return "Using SpacePilot hosted AI. Sign-in and hosted quotas may be required.";
 return "Connect OpenRouter, Groq, or SpacePilot AI in Settings for generative answers. Local deterministic answers still work without an AI provider.";
}
function aiErrorMessage(error:unknown){
 const value=String(error);
 if(value.includes("AUTH_REQUIRED"))return "Sign in to use SpacePilot hosted AI. BYOK OpenRouter/Groq can be used without signing in.";
 if(value.includes("OPENROUTER_INVALID_KEY"))return "OpenRouter rejected this key. Replace it in Settings and test again.";
 if(value.includes("GROQ_INVALID_KEY"))return "Groq rejected this key. Replace it in Settings and test again.";
 if(value.includes("AI_PROVIDER_RATE_LIMIT"))return "The selected AI provider rate limited this request. Try again later or choose another provider.";
 if(value.includes("AI_PROVIDER_TIMEOUT"))return "The selected AI provider timed out. Try again later.";
 if(value.includes("AI_PROVIDER_MODEL_NOT_FOUND"))return "The selected model was not found or is not available for this provider. Choose another model in Settings.";
 if(value.includes("AI_PROVIDER_UNAVAILABLE"))return "The selected AI provider is unavailable right now. Local storage tools still work.";
 if(value.includes("AI_PROVIDER_NOT_CONNECTED"))return "Connect and test an AI provider in Settings before asking cloud questions.";
 if(value.includes("AI_PROVIDER_REJECTED"))return "The selected AI provider rejected the request. Check the key, model name, and provider account limits.";
 if(value.includes("AI_USAGE_LIMIT_REACHED"))return "You reached SpacePilot's local BYOK safety limit of 25 successful AI requests today.";
 if(value.includes("BACKEND_UNAVAILABLE"))return "SpacePilot hosted AI is unavailable. Local storage tools still work.";
 return "AI Copilot could not complete this request. Local storage tools still work.";
}
