 const[input,setInput]=useState(""),[turns,setTurns]=useState<{question:string;response:AiCopilotResponse}[]>([]),[loading,setLoading]=useState(false),[aiError,setAiError]=useState(""),[fileQuery,setFileQuery]=useState(""),[matches,setMatches]=useState<FileInspectorMatch[]>([]),[pendingFile,setPendingFile]=useState<{path:string;name:string;size:number;extension:string;outside:boolean}|null>(null),[fileNotice,setFileNotice]=useState("");
